} from '@/components/ui/select'

const TIMEZONES = [
  'America/New_York',
  'America/Chicago',
  'America/Denver',
  'America/Los_Angeles',
  'America/Anchorage',
  'Pacific/Honolulu',
  'Europe/London',
  'Europe/Paris',
  'Europe/Berlin',
  'Asia/Tokyo',
  'Asia/Shanghai',
  'Australia/Sydney',
]

const step1Schema = z.object({
  studioName: z.string().min(2, 'At least 2 characters').max(60),
  timezone: z.string().min(1, 'Select a timezone'),
})

type Step1Values = z.infer<typeof step1Schema>

interface StepStudioProfileProps {
  studioId: string | null
  onNext: () => void
}

export function StepStudioProfile({ studioId, onNext }: StepStudioProfileProps) {
  const supabase = createClient()
  const fileInputRef = useRef<HTMLInputElement>(null)
  const [isDragging, setIsDragging] = useState(false)
  const [logoPreview, setLogoPreview] = useState<string | null>(null)
  const [logoFile, setLogoFile] = useState<File | null>(null)
  const [saving, setSaving] = useState(false)

  const {
    register,
    handleSubmit,
    setValue,
    formState: { errors },
  } = useForm<Step1Values>({
    resolver: zodResolver(step1Schema),
    defaultValues: { timezone: 'America/New_York' },
  })

  function handleFileSelect(file: File) {
    if (file.size > 2 * 1024 * 1024) {
      toast.error('Logo must be under 2 MB')
      return
    }
    if (!['image/png', 'image/jpeg', 'image/svg+xml'].includes(file.type)) {
      toast.error('PNG, JPG, or SVG only')
      return
    }
    setLogoFile(file)
    const url = URL.createObjectURL(file)
    setLogoPreview(url)
    toast.success('Logo uploaded')
  }

  async function onSubmit(data: Step1Values) {
    setSaving(true)
    try {
      let logoUrl: string | null = null

      // Upload logo if provided
      if (logoFile && studioId) {
        const ext = logoFile.name.split('.').pop() ?? 'png'
        const path = `${studioId}/logo.${ext}`
        const { error: uploadError } = await supabase.storage
          .from('studio-assets')
          .upload(path, logoFile, { upsert: true })
        if (uploadError) throw uploadError

        const { data: urlData } = supabase.storage
          .from('studio-assets')
          .getPublicUrl(path)
        logoUrl = urlData.publicUrl
      }

      // Update studio
      if (studioId) {
        const { error } = await supabase
          .from('studios')
          .update({
            name: data.studioName,
            timezone: data.timezone,
            ...(logoUrl ? { logo_url: logoUrl } : {}),
          })
          .eq('id', studioId)
        if (error) throw error
      }

      onNext()
    } catch (err) {
      toast.error(
        `Couldn't save — ${err instanceof Error ? err.message : 'Unknown error'}`,
      )
    } finally {
      setSaving(false)
    }
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-5">
      <div>
        <h2 className="text-xl font-bold tracking-tight">
          Let&#39;s set up your studio
        </h2>
        <p className="mt-1 text-sm text-muted-foreground">
          Your public booking page goes live in under 2 minutes
        </p>
      </div>

      <div className="space-y-1.5">
        <Label htmlFor="studioName">
          Studio name <span className="text-destructive">*</span>
        </Label>
        <Input
          id="studioName"
          placeholder="Dark Matter Tattoo"
          autoComplete="organization"
          aria-describedby={errors.studioName ? 'studioName-error' : undefined}
          aria-invalid={!!errors.studioName}
          {...register('studioName')}
        />
        {errors.studioName && (
          <p id="studioName-error" role="alert" className="text-xs text-destructive">
            {errors.studioName.message}
          </p>
        )}
      </div>

      <div className="space-y-1.5">
        <Label htmlFor="timezone">
          Timezone <span className="text-destructive">*</span>
        </Label>
        <Select
          defaultValue="America/New_York"
          onValueChange={(v) => setValue('timezone', v)}
        >
          <SelectTrigger id="timezone">
            <SelectValue placeholder="Select timezone" />
          </SelectTrigger>
          <SelectContent>
            {TIMEZONES.map((tz) => (
              <SelectItem key={tz} value={tz}>
                {tz}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        {errors.timezone && (
          <p role="alert" className="text-xs text-destructive">
            {errors.timezone.message}
          </p>
        )}
      </div>

      <div className="space-y-1.5">
        <Label>Studio logo (optional)</Label>
        <div
          role="button"
          tabIndex={0}
          aria-label="Upload studio logo"
          className={[
            'cursor-pointer rounded-lg border-2 border-dashed p-6 text-center transition-colors',
            isDragging
              ? 'border-primary/60 bg-primary/[0.04]'
              : 'border-border hover:border-primary/40',
          ].join(' ')}
          onClick={() => fileInputRef.current?.click()}
          onKeyDown={(e) => e.key === 'Enter' && fileInputRef.current?.click()}
          onDragOver={(e) => {
            e.preventDefault()
            setIsDragging(true)
          }}
          onDragLeave={() => setIsDragging(false)}
          onDrop={(e) => {
            e.preventDefault()
            setIsDragging(false)
            const file = e.dataTransfer.files[0]
            if (file) handleFileSelect(file)
          }}
        >
          {logoPreview ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={logoPreview}
              alt="Logo preview"
              className="mx-auto h-16 w-16 rounded object-contain"
            />
          ) : (
            <>
              <Upload
                className="mx-auto mb-2 h-6 w-6 text-muted-foreground/50"
                aria-hidden="true"
              />
              <p className="text-sm text-muted-foreground">
                Drop your logo here or browse
              </p>
              <p className="mt-0.5 text-xs text-muted-foreground/60">
                PNG, JPG or SVG · Max 2MB
              </p>
            </>
          )}
        </div>
        <input
          ref={fileInputRef}
          type="file"
          accept="image/png,image/jpeg,image/svg+xml"
          className="sr-only"
          onChange={(e) => {
            const file = e.target.files?.[0]
            if (file) handleFileSelect(file)
          }}
        />
      </div>

      <div className="flex justify-end pt-2">
        <Button type="submit" disabled={saving}>
          {saving ? 'Saving...' : 'Continue →'}
        </Button>
      </div>
    </form>
  )
}

