'use client'

import { useState } from 'react'
import { useForm } from 'react-hook-form'
import { zodResolver } from '@hookform/resolvers/zod'
import { z } from 'zod'
import { toast } from 'sonner'
import { createClient } from '@/lib/supabase/client'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { cn } from '@/lib/utils'

const SPECIALTY_OPTIONS = [
  'Blackwork',
  'Watercolor',
  'Traditional',
  'Neo-trad',
  'Realism',
  'Geometric',
  'Minimalist',
  'Portraits',
  'Script',
  'Cover-up',
]

const step3Schema = z.object({
  artistName: z.string().min(2, 'At least 2 characters').max(80),
  artistEmail: z
    .string()
    .email('Enter a valid email')
    .optional()
    .or(z.literal('')),
  specialties: z.array(z.string()).optional(),
})

type Step3Values = z.infer<typeof step3Schema>

interface StepFirstArtistProps {
  studioId: string | null
  userId: string
  onNext: () => void
  onBack: () => void
}

export function StepFirstArtist({
  studioId,
  userId,
  onNext,
  onBack,
}: StepFirstArtistProps) {
  const supabase = createClient()
  const [saving, setSaving] = useState(false)
  const [selectedSpecialties, setSelectedSpecialties] = useState<string[]>([])

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<Step3Values>({
    resolver: zodResolver(step3Schema),
  })

  function toggleSpecialty(specialty: string) {
    setSelectedSpecialties((prev) =>
      prev.includes(specialty)
        ? prev.filter((s) => s !== specialty)
        : [...prev, specialty],
    )
  }

  async function onSubmit(data: Step3Values) {
    if (!studioId) {
      toast.error("Couldn't save — No studio found")
      return
    }

    setSaving(true)
    try {
      // Sprint 1: Store artist in profiles + studio_members (artists table is Sprint 2)
      // Update the profile name if not set
      await supabase
        .from('profiles')
        .update({ full_name: data.artistName })
        .eq('id', userId)

      // Upsert studio_member record (already exists from signup trigger, but ensure role is correct)
      const { error: memberError } = await supabase
        .from('studio_members')
        .upsert(
          {
            studio_id: studioId,
            user_id: userId,
            role: 'owner',
          },
          { onConflict: 'studio_id,user_id' },
        )
      if (memberError) throw memberError

      // Store specialties in localStorage for Sprint 2 migration
      if (selectedSpecialties.length > 0) {
        localStorage.setItem(
          'inkos-onboarding-specialties',
          JSON.stringify(selectedSpecialties),
        )
      }
      if (data.artistEmail) {
        localStorage.setItem('inkos-onboarding-artist-email', data.artistEmail)
      }

      onNext()
    } catch (err) {
      toast.error(
        `Couldn't save — ${err instanceof Error ? err.message : 'Unknown error'}`,
      )
    } finally {
      setSaving(false)
    }
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-5">
      <div>
        <h2 className="text-xl font-bold tracking-tight">
          Add your first artist
        </h2>
        <p className="mt-1 text-sm text-muted-foreground">
          That&#39;s probably you
        </p>
      </div>

      <div className="space-y-1.5">
        <Label htmlFor="artistName">
          Full name <span className="text-destructive">*</span>
        </Label>
        <Input
          id="artistName"
          autoComplete="name"
          {...register('artistName')}
          aria-invalid={!!errors.artistName}
        />
        {errors.artistName && (
          <p role="alert" className="text-xs text-destructive">
            {errors.artistName.message}
          </p>
        )}
      </div>

      <div className="space-y-1.5">
        <Label htmlFor="artistEmail">Artist email (for invite)</Label>
        <Input
          id="artistEmail"
          type="email"
          autoComplete="email"
          {...register('artistEmail')}
          aria-invalid={!!errors.artistEmail}
        />
        {errors.artistEmail && (
          <p role="alert" className="text-xs text-destructive">
            {errors.artistEmail.message}
          </p>
        )}
        <p className="text-xs text-muted-foreground">
          They&#39;ll get a login invite after setup
        </p>
      </div>

      <div className="space-y-2">
        <Label>Specialties (optional)</Label>
        <div className="flex flex-wrap gap-2">
          {SPECIALTY_OPTIONS.map((specialty) => {
            const selected = selectedSpecialties.includes(specialty)
            return (
              <button
                key={specialty}
                type="button"
                onClick={() => toggleSpecialty(specialty)}
                className={cn(
                  'h-7 rounded-full border px-3 text-xs transition-colors',
                  selected
                    ? 'border-primary/30 bg-primary/15 text-primary'
                    : 'border-border bg-transparent text-muted-foreground hover:border-border/80 hover:text-foreground',
                )}
              >
                {specialty}
                {selected && <span className="ml-1">×</span>}
              </button>
            )
          })}
        </div>
      </div>

      <div className="flex items-center justify-between pt-2">
        <Button type="button" variant="ghost" onClick={onBack}>
          ← Back
        </Button>
        <Button type="submit" disabled={saving}>
          {saving ? 'Saving...' : 'Continue →'}
        </Button>
      </div>
    </form>
  )
}

'use client'

import { useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import { CheckCircle2, Copy, ExternalLink } from 'lucide-react'
import { toast } from 'sonner'
import { createClient } from '@/lib/supabase/client'
import { Button } from '@/components/ui/button'

interface StepBookingPageLiveProps {
  studioId: string | null
  startTime: number
  onBack: () => void
}

export function StepBookingPageLive({
  studioId,
  startTime,
  onBack,
}: StepBookingPageLiveProps) {
  const router = useRouter()
  const supabase = createClient()
  const [slug, setSlug] = useState<string | null>(null)

  useEffect(() => {
    if (!studioId) return

    supabase
      .from('studios')
      .select('slug')
      .eq('id', studioId)
      .single()
      .then(({ data }) => {
        if (data?.slug) setSlug(data.slug)
      })

    // Fire PostHog event
    const durationSeconds = Math.round((Date.now() - startTime) / 1000)
    if (typeof window !== 'undefined' && 'posthog' in window) {
      // @ts-expect-error — posthog is loaded via script tag
      window.posthog?.capture?.('onboarding_completed', {
        studioId,
        stepsCompleted: 5,
        duration_seconds: durationSeconds,
      })
    }

    // Clear onboarding step from localStorage — they're done
    localStorage.removeItem('inkos-onboarding-step')
  }, [studioId, startTime, supabase])

  const bookingUrl = slug ? `book.inkos.app/${slug}` : 'Generating...'

  function handleCopy() {
    if (!slug) return
    navigator.clipboard
      .writeText(`https://${bookingUrl}`)
      .then(() => toast.success('Link copied to clipboard'))
      .catch(() => toast.error('Could not copy to clipboard'))
  }

  function handleGoToDashboard() {
    router.push('/dashboard')
    router.refresh()
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col items-center text-center">
        <CheckCircle2
          className="mb-4 h-14 w-14 text-primary"
          style={{ filter: 'drop-shadow(0 0 20px oklch(72% 0.28 292 / 0.4))' }}
          aria-hidden="true"
        />
        <h2 className="text-xl font-bold tracking-tight">
          Your studio is live
        </h2>
        <p className="mt-1 text-sm text-muted-foreground">
          Clients can now book online
        </p>
      </div>

      {/* Booking link */}
      <div className="rounded-lg bg-muted/30 p-4">
        <p className="mb-1 text-[10px] font-semibold uppercase tracking-widest text-muted-foreground">
          Your booking link
        </p>
        <p className="mb-3 font-mono text-sm text-foreground">{bookingUrl}</p>
        <div className="flex gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={handleCopy}
            disabled={!slug}
          >
            <Copy className="mr-1.5 h-3.5 w-3.5" aria-hidden="true" />
            Copy link
          </Button>
          {slug && (
            <Button variant="outline" size="sm" asChild>
              <a
                href={`https://${bookingUrl}`}
                target="_blank"
                rel="noopener noreferrer"
              >
                <ExternalLink className="mr-1.5 h-3.5 w-3.5" aria-hidden="true" />
                Open preview
              </a>
            </Button>
          )}
        </div>
      </div>

      {/* What's next */}
      <div>
        <p className="mb-3 text-sm font-medium">What&#39;s next:</p>
        <ul className="space-y-2">
          {[
            'Invite your team',
            'Add more services',
            'Connect Google Calendar',
          ].map((item) => (
            <li key={item} className="flex items-center gap-2 text-sm text-muted-foreground">
              <span className="h-1.5 w-1.5 rounded-full bg-muted-foreground/40" aria-hidden="true" />
              {item}
            </li>
          ))}
        </ul>
      </div>

      <div className="flex items-center justify-between pt-2">
        <Button type="button" variant="ghost" onClick={onBack}>
          ← Back
        </Button>
        <Button onClick={handleGoToDashboard} className="w-full max-w-[200px]">
          Go to dashboard →
        </Button>
      </div>
    </div>
  )
}

